import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'pricing-card-1-accent';

  const content = new THREE.Group();
  root.add(content);

  const colors = (config.intent?.visualSpec?.colors) ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10',
  };

  // ---- sizing from atlas region aspect ----
  const rect = config.atlasRegion?.rect ?? { w: 512, h: 320 };
  const aspect = (rect.w ?? 512) / (rect.h ?? 320);
  const width = 1.7;
  const height = width / aspect;

  // ---- engineered gradient backdrop panel (behind the accent image) ----
  const panelGeo = new THREE.PlaneGeometry(width * 1.12, height * 1.22, 1, 1);
  const panelMat = new MeshStandardNodeMaterial({
    roughness: 0.62,
    metalness: 0.32,
    side: THREE.FrontSide,
  });

  const uvNode = uv();
  const colorSurface = color(colors.surface);
  const colorInk = color(colors.ink);
  const colorAccent = color(colors.accent);

  const base = mix(colorSurface, colorInk, uvNode.y);

  // subtle procedural grain (static, breaks flatness without motion)
  const grain = uvNode
    .dot(vec2(12.9898, 78.233))
    .sin()
    .mul(43758.5453)
    .fract()
    .sub(0.5)
    .mul(0.028);

  // thin accent stripe near the base of the card (<=10% of area)
  const bandCenter = 0.06;
  const dist = uvNode.y.sub(bandCenter).abs();
  const band = float(1.0).sub(smoothstep(0.0, 0.018, dist));
  const withStripe = mix(base, colorAccent, band.mul(0.55));

  panelMat.colorNode = withStripe.add(grain);

  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.z = -0.03;
  content.add(panel);

  // node-local rim light so the brushed panel reads with a highlight edge
  const rim = new THREE.DirectionalLight(0xffe9e6, 0.55);
  rim.position.set(-1.2, 0.8, 1.4);
  content.add(rim);

  // ---- foreground: textured accent sprite plane ----
  const spriteGeo = new THREE.PlaneGeometry(width, height, 1, 1);
  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.FrontSide,
  });
  const spriteMesh = new THREE.Mesh(spriteGeo, spriteMat);
  spriteMesh.position.z = 0.02;
  content.add(spriteMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      tex.offset.set(0, 0);
      tex.repeat.set(1, 1);
      spriteMat.map = tex;
      spriteMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- motion: weighted entrance + single slow breathing idle ----
  const timelines = [];

  content.scale.setScalar(0.98);
  content.position.y -= 0.12;

  const introTl = gsap.timeline();
  introTl.to(content.position, {
    y: content.position.y + 0.12,
    duration: 0.7,
    ease: 'power3.out',
  });
  introTl.to(content.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  introTl.to(content.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.5,
    ease: 'power2.out',
  }, 0.9);
  timelines.push(introTl);

  const breatheTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.4 });
  breatheTl.to(content.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 4.0,
    ease: 'sine.inOut',
  });
  timelines.push(breatheTl);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    panelGeo.dispose();
    panelMat.dispose();
    spriteGeo.dispose();
    spriteMat.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    rim.dispose?.();
  };

  return root;
}
